use std::path::Path;

fn main() {
    // tauri-build checks that every bundle resource exists. The third-party
    // notices are generated by `npm run notices` (Tauri's beforeBuildCommand)
    // before a bundle; a plain `cargo build` or `cargo test` gets a stub.
    let notices = Path::new("notices/THIRD_PARTY_NOTICES.txt");
    if !notices.exists() {
        std::fs::create_dir_all("notices").expect("create notices/");
        std::fs::write(notices, "Third-party notices are generated by `npm run notices` for a bundle.\n")
            .expect("write the notices stub");
    }
    // tauri-build embeds the Windows app manifest (common controls v6) into the
    // app binary only. Test binaries linking tauri's `test` feature need it too,
    // or they fail to load with STATUS_ENTRYPOINT_NOT_FOUND, so the linker
    // embeds it into every binary instead.
    let mut attributes = tauri_build::Attributes::new();
    if std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
        attributes = attributes.windows_attributes(tauri_build::WindowsAttributes::new_without_app_manifest());
        let manifest = Path::new(env!("CARGO_MANIFEST_DIR")).join("windows-app-manifest.xml");
        println!("cargo:rerun-if-changed=windows-app-manifest.xml");
        println!("cargo:rustc-link-arg=/MANIFEST:EMBED");
        println!("cargo:rustc-link-arg=/MANIFESTINPUT:{}", manifest.display());
    }
    tauri_build::try_build(attributes).expect("tauri-build")
}
